Vamos criar uma aplicação mínima e o Dockerfile dela. O `cat > arquivo <<'EOF'` grava o texto até a linha EOF (use as aspas em `'EOF'` para o shell não expandir variáveis).

Esta é a *nossa aplicação*: um servidor Node.js sem dependências externas, que responde na porta 3000.

Antes de remover ou recriar recursos, confirme o nome com `docker ps -a` e verifique se **os dados importantes estão em um volume**.
```bash
mkdir minha-app && cd minha-app

cat > server.js <<'EOF'
const http = require('http');
http.createServer((req, res) => {
  res.end('Ola do container! Versao 1\n');
}).listen(3000, '0.0.0.0', () => console.log('Servidor na porta 3000'));
EOF

cat > package.json <<'EOF'
{ "name": "minha-app", "version": "1.0.0", "scripts": { "start": "node server.js" } }
EOF
```

A API conecta no banco usando variáveis de ambiente, cria a tabela se não existir (com retry) e expõe três rotas: `/health`, `GET /tasks` e `POST /tasks`.
```bash
cat > server.js <<'EOF'
const express = require('express');
const { Pool } = require('pg');

const pool = new Pool({
  host: process.env.DB_HOST,
  port: Number(process.env.DB_PORT || 5432),
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  database: process.env.DB_NAME,
});

const app = express();
app.use(express.json());

app.get('/health', async (req, res) => {
  try { await pool.query('SELECT 1'); res.json({ status: 'ok' }); }
  catch (e) { res.status(503).json({ status: 'db indisponivel' }); }
});

app.get('/tasks', async (req, res) => {
  const r = await pool.query('SELECT * FROM tasks ORDER BY id');
  res.json(r.rows);
});

app.post('/tasks', async (req, res) => {
  const r = await pool.query('INSERT INTO tasks (title) VALUES ($1) RETURNING *', [req.body.title]);
  res.status(201).json(r.rows[0]);
});

async function init(tentativas = 10) {
  try {
    await pool.query('CREATE TABLE IF NOT EXISTS tasks (id SERIAL PRIMARY KEY, title TEXT NOT NULL)');
    app.listen(3000, '0.0.0.0', () => console.log('API na porta 3000'));
  } catch (e) {
    if (tentativas === 0) { console.error('Sem conexao com o banco', e.message); process.exit(1); }
    console.log('Aguardando banco... restam', tentativas);
    setTimeout(() => init(tentativas - 1), 2000);
  }
}
init();
EOF
```

